SELECT 'ALE-DSGN-009-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-DSGN-009'), 3, 'Passive Environmental Design - Sun, Wind, Thermal Mass', 'Architectural Design and Site Planning', 'fact'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Solar orientation Philippines: sun path varies latitude (Manila ~14°N)", "type": "fact"}, {"text": "Summer sun angle: high overhead (60-80° altitude), minimized by horizontal overhangs", "type": "fact"}, {"text": "Winter sun angle: lower (20-30° altitude), allows beneficial heat gain", "type": "fact"}, {"text": "Overhang depth calculation: 0.8-1.0m per meter of vertical window height typical", "type": "fact"}, {"text": "Window-to-wall ratio: 20-30% optimal for tropical climate (reduces heat gain)", "type": "fact"}, {"text": "East/West exposure: minimize heat gain with overhangs, louvers, vegetation", "type": "fact"}, {"text": "North/South orientation: North façade (Southern Hemisphere) gets consistent light without heat", "type": "fact"}, {"text": "Ventilation strategy: cross-ventilation 8-12m maximum building depth for natural air movement", "type": "fact"}, {"text": "Wind patterns Philippines: monsoon seasons (SW May-September, NE November-March)", "type": "fact"}, {"text": "Thermal mass: concrete/masonry provides thermal inertia, reduces daily temperature swings", "type": "fact"}, {"text": "Night cooling: opening windows during cooler night hours to pre-cool spaces", "type": "fact"}, {"text": "Vegetation strategy: deciduous trees for summer shade, allow winter sun", "type": "fact"}, {"text": "Green roofs/walls: reduces surface temperature 10-15°C, increases insulation", "type": "fact"}, {"text": "Standards Applied: DOE Guidelines on Energy Conserving Design, Tropical Architecture Principles", "type": "concept"}]'::jsonb, true, false, false, false, 'ale-dsgn-009-01'
