SELECT 'ALE-DSGN-010-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-DSGN-010'), 3, 'Parking Structure Design and Geometry', 'Architectural Design and Site Planning', 'fact'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Surface parking lot: suitable for 50-150 spaces (beyond becomes inefficient land use)", "type": "fact"}, {"text": "Parking deck: 4-8 levels typical in urban areas (reduces footprint)", "type": "fact"}, {"text": "Structured parking density: 200-300 spaces per hectare typical (vs. 40-50 surface)", "type": "fact"}, {"text": "Deck configuration: linear ramp, central ramp, helical ramp, or elevator", "type": "fact"}, {"text": "Linear ramp: efficient for 100-300 spaces, slope 1:8-1:10 typical", "type": "fact"}, {"text": "Helical ramp: efficient use of space, psychological benefit (continuous spiral)", "type": "fact"}, {"text": "Mechanical stacking: double-stack lifts (one space becomes 2 vertical), reduces footprint 40%", "type": "fact"}, {"text": "Vehicle clearance: minimum 2.0-2.1m height (standard sedan), 2.2-2.4m for SUVs/trucks", "type": "fact"}, {"text": "Ventilation: natural cross-ventilation or mechanical fans (minimum 6 air changes/hour)", "type": "fact"}, {"text": "Lighting: 10-20 foot-candles for safety, LED increasingly used for efficiency", "type": "fact"}, {"text": "Drainage: sloped at 2% minimum to prevent standing water, french drain perimeter", "type": "fact"}, {"text": "Safety features: bumper barriers, column padding, markings and signage", "type": "fact"}, {"text": "Elevator in parking: 2.0m width × 2.5m depth minimum for car, 2.5m × 4.0m for van spaces", "type": "fact"}, {"text": "Standards Applied: Parking Design Manual (ITE), Time-Saver Standards", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-dsgn-010-02'
