SELECT 'ALE-DSGN-010-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-DSGN-010'), 3, 'Vehicular Circulation and Site Access Planning', 'Architectural Design and Site Planning', 'fact'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Entrance/exit separation: preferably on different roads, or minimum 20-30m spacing", "type": "fact"}, {"text": "Entrance width: 3.5m minimum (two lanes for entry traffic)", "type": "fact"}, {"text": "Exit width: 3.5-4.0m minimum (exit only, no merging)", "type": "fact"}, {"text": "Drop-off zone dimensions: 3.0m width × 6.0m length per bay (minimum 2 bays for major buildings)", "type": "fact"}, {"text": "Loading dock: 3.0m width × 12.0m depth minimum per bay", "type": "fact"}, {"text": "Service road width: 3.5m one-way, 7.0m two-way minimum", "type": "fact"}, {"text": "Right-of-way turn radius: 6-9m (allows tractor-trailer navigation)", "type": "fact"}, {"text": "Truck turning radius: 12-15m minimum (longer for refuse trucks)", "type": "fact"}, {"text": "Queue spacing: adequate storage for traffic queuing at entry (100-150m minimum for major buildings)", "type": "fact"}, {"text": "Internal circulation width: 4.0-5.0m minimum two-way, 3.0m one-way", "type": "fact"}, {"text": "Speed control: use of humps (8cm height, 4m width) to manage speeds (20-30 kph in lots)", "type": "fact"}, {"text": "Pedestrian conflict zones: minimize crossing of vehicle paths, use underpasses where possible", "type": "fact"}, {"text": "Accessible access route: connects accessible parking to building entrance via 1.5m minimum path", "type": "fact"}, {"text": "Standards Applied: PD 1096 Development Controls, Traffic Engineering Standards", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-dsgn-010-03'
