SELECT 'ALE-DSGN-011-01', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-DSGN-011'), 3, 'Architectural Floor Plans - Conventions and Standards', 'Architectural Design and Site Planning', 'fact'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Floor plan definition: horizontal section at 1.2-1.5m height showing walls, doors, fixtures, furniture", "type": "definition"}, {"text": "Scale: typical 1:100 for design development, 1:50 for detailed design", "type": "fact"}, {"text": "Line weights: walls thick (0.5-0.7mm), door swings medium (0.3-0.4mm), dimensions thin (0.2mm)", "type": "fact"}, {"text": "Wall thickness representation: actual thickness shown (typically 0.15-0.20m for partitions, 0.25m+ for structural)", "type": "fact"}, {"text": "Door swing direction: arc showing 90° swing, indicating swing direction", "type": "fact"}, {"text": "Door symbols: exterior doors with threshold, interior hinged/sliding/pocket options", "type": "fact"}, {"text": "Window symbols: straight line for fixed, markings for operable, dimension indicates opening width", "type": "fact"}, {"text": "Fixture dimensions: toilet 0.75m × 1.5m clearance space, bathtub 0.75m × 1.5m, sink counter height 0.85m", "type": "fact"}, {"text": "Stairs representation: line drawing showing tread/riser, arrow indicating up/down, annotations for rise/run", "type": "fact"}, {"text": "Dimensions: plan dimensions outside wall faces, internal dimensions to centerlines of walls or fixtures", "type": "fact"}, {"text": "Dimension lines: placed 0.5-1.0m from object, grouped hierarchically (small details near plan, major dimensions outside)", "type": "fact"}, {"text": "Notation: room names, square footage, floor levels, section/elevation marks", "type": "fact"}, {"text": "Legends: indicate material patterns (brick, concrete, tile), north arrow, scale", "type": "fact"}, {"text": "Bubble diagrams: space adjacency representations during programming phase", "type": "fact"}, {"text": "Furniture layouts: scaled furniture symbols showing space utilization and clearances", "type": "fact"}, {"text": "Standards Applied: Architectural Drawing Standards (Ching), AIA Standards, ISO Technical Drawing Standards", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-dsgn-011-01'
FROM public.disciplines d WHERE d.acronym = 'ALE'
ON CONFLICT (ale_id) DO UPDATE SET name = EXCLUDED.name, exam_frequency = EXCLUDED.exam_frequency, bloom_level = EXCLUDED.bloom_level, difficulty = EXCLUDED.difficulty, typical_question_formats = EXCLUDED.typical_question_formats, wiki_items = EXCLUDED.wiki_items, is_computation_heavy = EXCLUDED.is_computation_heavy, three_d_lab_linked = EXCLUDED.three_d_lab_linked, updated_at = now();
