SELECT 'ALE-DSGN-011-02', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-DSGN-011'), 3, 'Elevations and Sections - Vertical Representation', 'Architectural Design and Site Planning', 'fact'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Elevation definition: orthogonal projection showing vertical building face and major architectural features", "type": "definition"}, {"text": "Scale: same as floor plans (1:100, 1:50, 1:200 for large buildings)", "type": "fact"}, {"text": "Elevation types: front, rear, left side, right side (based on north orientation)", "type": "fact"}, {"text": "Height references: finished floor level (FFL), finished grade (FG), datum line for measurement", "type": "fact"}, {"text": "Material representation: hatching or pattern for brick, concrete, tile, glass, metal", "type": "fact"}, {"text": "Window representation: grid showing mullions, sill height dimensions, head height", "type": "fact"}, {"text": "Door placement: showing type, dimensions, approach/landing requirements", "type": "concept"}, {"text": "Roofline: eave dimensions, slope indication, materials", "type": "fact"}, {"text": "Balconies/terraces: projection dimension, parapet heights, railings", "type": "fact"}, {"text": "Section definition: vertical slice through building showing interior spatial relationships", "type": "definition"}, {"text": "Section line placement: shown on floor plan, labeled A-A'', B-B'' corresponding to section drawings", "type": "fact"}, {"text": "Section content: walls, floors, ceiling heights, structural elements, mechanical systems routing", "type": "fact"}, {"text": "Section scales: often 1:50 for detail, 1:100 for building sections", "type": "fact"}, {"text": "Building section: runs entire height showing roof-to-ground conditions", "type": "fact"}, {"text": "Wall section: detail showing exterior wall assembly (insulation, air barrier, finishes)", "type": "fact"}, {"text": "Key section locations: through main circulation, mechanical cores, major functional zones", "type": "fact"}, {"text": "Cross-section: shows depth relationships (important for understanding spatial proportions)", "type": "fact"}, {"text": "Longitudinal section: shows length of building", "type": "fact"}, {"text": "Standards Applied: Architectural Drawing Standards (Ching), Construction Documentation Standards", "type": "fact"}]'::jsonb, true, false, false, false, 'ale-dsgn-011-02'
