SELECT 'ALE-DSGN-011-03', d.discipline_id, (SELECT node_id FROM public.taxonomy_tree WHERE ale_id = 'ALE-DSGN-011'), 3, 'Site Plans and Context Drawings', 'Architectural Design and Site Planning', 'fact'::public.taxonomy_node_type, 'high'::public.exam_frequency_level, 'apply'::public.bloom_level_type, 3, ARRAY['mcq_recall','mcq_application'], '[{"text": "Site plan definition: top-down orthogonal view of entire property showing buildings, circulation, landscape", "type": "definition"}, {"text": "Scale: 1:200, 1:500, or 1:1000 depending on site size", "type": "fact"}, {"text": "Site boundary: property lines with dimensions and legal description", "type": "fact"}, {"text": "Existing conditions: topography (contours at 0.5-1.0m intervals), existing vegetation, utilities", "type": "fact"}, {"text": "Building footprint: shown with setbacks from property lines, dimensions, orientation", "type": "fact"}, {"text": "Access and circulation: pedestrian paths, vehicular drives, emergency access, parking areas", "type": "fact"}, {"text": "Landscape elements: trees, shrubs, planting areas, open space, plazas", "type": "fact"}, {"text": "Parking layout: showing stalls (dimensioned rows), aisles, accessible spaces, circulation", "type": "fact"}, {"text": "Utility infrastructure: water main, sewer line, electrical, gas, storm drainage routing", "type": "fact"}, {"text": "North arrow: clearly indicated (usually top of page or rotated to actual orientation)", "type": "fact"}, {"text": "Spot elevations: ground level at key points (entry, corners, parking areas)", "type": "fact"}, {"text": "Section/elevation marks: indicating where building sections/elevations are cut", "type": "fact"}, {"text": "Grading plan: slope arrows showing drainage direction, swales, retention areas", "type": "fact"}, {"text": "Setback dimensions: from front, side, rear property lines to building faces", "type": "fact"}, {"text": "Building coverage calculations: percentage of lot covered by building(s), remaining