UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Accessible toilet stall dimensions: 1.5m width × 2.0m depth minimum", "type": "fact"}, {"text": "Water closet (WC) height: 0.40-0.43m from finished floor", "type": "fact"}, {"text": "Grab bar specifications: 0.032-0.038m diameter, 1.2m length, mounted 0.75-0.95m high", "type": "fact"}, {"text": "Toilet paper holder location: 0.10-0.15m from toilet centerline", "type": "fact"}, {"text": "Lavatory (sink) height: 0.75-0.85m from finished floor", "type": "fact"}, {"text": "Lavatory knee clearance: minimum 0.30m height × 0.20m depth", "type": "fact"}, {"text": "Mirror height: bottom edge 0.40m maximum from floor", "type": "fact"}, {"text": "Soap, towel, dryer dispensers: located 0.40-1.35m high", "type": "fact"}, {"text": "Shower/bathtub grab bars and seat specifications", "type": "fact"}, {"text": "Changing room requirements: accessible dressing area with seating", "type": "fact"}, {"text": "Proportion requirement: 1 accessible toilet per occupancy (minimum 1)", "type": "fact"}, {"text": "Standards Applied: BP 344 Section 4, Neufert/Time-Saver Bathroom Standards", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-002-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Minimum lot area: 150-300 sq.m. (varies by location and zoning)", "type": "fact"}, {"text": "Minimum lot frontage: 10-15m typical", "type": "fact"}, {"text": "Typical house setbacks: 5m front, 2m side, 3m rear (varies by zone)", "type": "fact"}, {"text": "Net floor area per occupant: 4-5 sq.m. (basic standards)", "type": "fact"}, {"text": "Bedrooms: minimum 1, typical 2-3", "type": "fact"}, {"text": "Bathroom: minimum 1 (1 per 2 bedrooms ideal)", "type": "fact"}, {"text": "Kitchen area: 6-8 sq.m. for small house, 8-12 sq.m. for medium", "type": "fact"}, {"text": "Living/dining area: 15-20 sq.m. combined", "type": "fact"}, {"text": "Garage/carport: 2.4m width × 5.0m depth per vehicle", "type": "fact"}, {"text": "Outdoor space: minimum 10% of lot area for amenities/landscaping", "type": "fact"}, {"text": "Site coverage maximum: 50-60% of lot area", "type": "fact"}, {"text": "Floor area ratio considerations for stacked/multi-story", "type": "fact"}, {"text": "Standards Applied: BP 220 (for socialized housing context), NBCP, Local Zoning Codes", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-003-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Unit width: 4-5m typical per unit (8-10m for duplex)", "type": "fact"}, {"text": "Unit depth: 10-15m typical", "type": "fact"}, {"text": "Unit floor area: 40-60 sq.m. per unit (1-bedroom), 60-100 sq.m. (2-3 bedroom)", "type": "fact"}, {"text": "Setbacks: shared party walls eliminate side setbacks (typically 3.0m between rowhouse groups)", "type": "fact"}, {"text": "Front setback: 3-5m, rear setback: 3m minimum", "type": "fact"}, {"text": "Parking: 1-1.5 spaces per unit minimum", "type": "fact"}, {"text": "Outdoor space: small yard or patio 3-4m deep minimum", "type": "fact"}, {"text": "Common circulation: shared entry court, walkways minimum 1.5m width", "type": "fact"}, {"text": "Density: 40-60 units per hectare typical", "type": "fact"}, {"text": "Privacy considerations: offsetting windows, acoustic privacy (50 dB reduction walls)", "type": "fact"}, {"text": "Waste management: centralized collection for multi-unit rowhouses", "type": "fact"}, {"text": "Fire separation walls: 2-hour fire rating minimum between units", "type": "fact"}, {"text": "Standards Applied: BP 220 Rowhouse Guidelines, NBCP Multi-Family Standards", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-003-02';
