UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Airport terminal occupancy: 1 person per 2-3 sq.m. (high-density public space)", "type": "fact"}, {"text": "Check-in counter: 1 counter per flight + 1 backup (10-15 flights typical = 15-20 counters)", "type": "fact"}, {"text": "Counter length: 3-4m per counter position", "type": "fact"}, {"text": "Check-in queuing area: 1.5-2.0 sq.m. per person (peak capacity)", "type": "fact"}, {"text": "Departure lounge: 0.3-0.5 sq.m. per passenger (sitting + standing)", "type": "fact"}, {"text": "Seating arrangement: 60% seats + 40% standing room", "type": "fact"}, {"text": "Gate area: 20-30 sq.m. per gate (excluding lounge)", "type": "fact"}, {"text": "Corridor width terminals: 3.0-4.0m minimum (peak passenger flows)", "type": "fact"}, {"text": "Baggage claim: 0.4-0.5 sq.m. per passenger", "type": "fact"}, {"text": "Parking: 1 space per 10-20 departing passengers (varies by airport type)", "type": "fact"}, {"text": "Port terminal: 1 person per 2-3 sq.m. (cargo/passenger)", "type": "fact"}, {"text": "Transit station/bus terminal occupancy: 1 person per 1.5-2.0 sq.m.", "type": "fact"}, {"text": "Bus bay depth: 12-15m per bus", "type": "fact"}, {"text": "Bus bay width: 3.0m minimum per bay", "type": "fact"}, {"text": "Waiting area: 0.3-0.4 sq.m. per passenger", "type": "fact"}, {"text": "Ticket counter: 1 per 1,000-2,000 expected daily passengers", "type": "fact"}, {"text": "Restroom facilities: 1 WC per 50-75 occupants (high-use facilities)", "type": "fact"}, {"text": "Standards Applied: International Terminal Standards (IATA, AACO), NBCP Assembly Occupancy", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-006-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Power plant occupancy: based on control room + maintenance staff (50-200 workers typical)", "type": "fact"}, {"text": "Control room: 80-150 sq.m. (climate-controlled)", "type": "fact"}, {"text": "Turbine hall height: 15-25m (large generators)", "type": "fact"}, {"text": "Machine hall width: 20-30m (for crane operation overhead)", "type": "fact"}, {"text": "Water treatment plant occupancy: 10-50 staff (depends on capacity)", "type": "fact"}, {"text": "Process tank size: 100-1,000 cubic meters (treatment capacity dependent)", "type": "concept"}, {"text": "Sedimentation tank: L:W ratio 3-4:1, depth 2-4m", "type": "fact"}, {"text": "Filtration building: 40-80 sq.m. typical (small systems)", "type": "fact"}, {"text": "Laboratory: 30-50 sq.m. (water quality testing)", "type": "fact"}, {"text": "Administrative office: 100-200 sq.m.", "type": "fact"}, {"text": "Mechanical: 15-20% of total facility area", "type": "fact"}, {"text": "Waste treatment plant: area varies by waste type (100-500 hectares for large landfills)", "type": "fact"}, {"text": "Facility office: 100-200 sq.m.", "type": "fact"}, {"text": "Parking requirement: 1 space per 2-3 employees (limited public access typically)", "type": "fact"}, {"text": "Standards Applied: DOH/DENR Infrastructure Standards, Utility Design Guidelines", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-006-03';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Program definition: detailed list of spaces required for a building type with area allocations", "type": "definition"}, {"text": "Data sources for programming: client brief, standards (Neufert, Time-Saver), precedent analysis, building codes", "type": "fact"}, {"text": "Occupant load determination: essential first step before sizing spaces", "type": "fact"}, {"text": "Net floor area (NFA): usable space exclusive of circulation and mechanical", "type": "fact"}, {"text": "Gross floor area (GFA): total building area including all spaces and walls", "type": "fact"}, {"text": "Efficiency ratio: NFA ÷ GFA (varies by building type: offices 75-85%, retail 60-70%, residential 65-80%)", "type": "fact"}, {"text": "Adjacency analysis: which spaces need to be close, which should be separate", "type": "fact"}, {"text": "Circulation efficiency: 15-35% of GFA typically (varies by building type)", "type": "fact"}, {"text": "Mechanical/vertical core area: 8-15% of GFA (elevators, stairs, HVAC, plumbing)", "type": "fact"}, {"text": "Structural grid determination: 6-9m typical for office, 9-12m for retail", "type": "fact"}, {"text": "Column-free span requirements: certain spaces need clear spans (ballrooms, manufacturing)", "type": "fact"}, {"text": "Modular space planning: designing to accommodate flexibility and future changes", "type": "fact"}, {"text": "Buffer zones: between incompatible uses (noise, odor, temperature)", "type": "fact"}, {"text": "Contingency area: 5-10% additional space for unknowns in programming", "type": "fact"}, {"text": "Database of typical space areas: referenced from Panero, De Chiara, Neufert standards", "type": "fact"}, {"text": "Standards Applied: Panero Time-Saver Standards for Architectural Design Data, Neufert Architects'' Data, De Chiara Building Types", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-007-01';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Bubble diagram purpose: graphical representation of space relationships during initial design phases", "type": "fact"}, {"text": "Bubble sizing: proportional to area allocations (larger bubble = larger space)", "type": "fact"}, {"text": "Adjacency relationships: required/preferred/avoided proximitities", "type": "fact"}, {"text": "Adjacency matrix construction: rows/columns for each space type, marks indicating relationship strength", "type": "fact"}, {"text": "Strong adjacency example: kitchen adjacent to dining area (service flow)", "type": "fact"}, {"text": "Weak/no adjacency: noisy manufacturing away from offices", "type": "fact"}, {"text": "Circulation hierarchy: primary (main movement), secondary (departmental), tertiary (occasional)", "type": "fact"}, {"text": "Zoning strategies: grouping spaces by function (office zone, retail zone, etc.)", "type": "fact"}, {"text": "Vertical circulation: location of stairs/elevators relative to major space clusters", "type": "fact"}, {"text": "Public/private separation: public entry away from service entries, staff areas secured", "type": "fact"}, {"text": "Service access: loading dock, trash, utilities separate from public circulation", "type": "fact"}, {"text": "Fire egress analysis: exits positioned relative to occupied spaces", "type": "fact"}, {"text": "Flexibility considerations: spaces designed to allow future modifications", "type": "fact"}, {"text": "Transition spaces: entry vestibules, lobbies as climate buffers and security checkpoints", "type": "fact"}, {"text": "Standards Applied: Architectural Design Methodology (Anderson, Ching)", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-007-02';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Single-loaded corridor: spaces on one side only (typical residential/hotel)", "type": "fact"}, {"text": "Double-loaded corridor: spaces on both sides (typical office, hospital)", "type": "fact"}, {"text": "Central atrium circulation: multi-story vertical void with balconies/ramps", "type": "fact"}, {"text": "Linear circulation: one main path (school hallway, retail main aisle)", "type": "fact"}, {"text": "Grid circulation: multiple pathways intersecting (campus, shopping center)", "type": "fact"}, {"text": "Radial circulation: paths emanating from central point (rotunda, plaza)", "type": "fact"}, {"text": "Corridor width standards: 1.2-1.5m minimum service corridor, 1.8-2.0m standard office, 2.4m+ emergency egress", "type": "fact"}, {"text": "Corridor length between exits: maximum 30-45m (varies with sprinklers, occupancy)", "type": "fact"}, {"text": "Dead-end corridor: permitted only to extent of 1.5× the width of corridor (or 7.5m maximum typical)", "type": "fact"}, {"text": "Stair/exit placement: positioned at ends of corridors when possible", "type": "fact"}, {"text": "Accessible route requirements: minimum 1.5m width, maximum 1:20 slope (5%)", "type": "fact"}, {"text": "Pedestrian flow rates: 1-2 persons per second per meter of width (peak design capacity)", "type": "fact"}, {"text": "Wayfinding: signage and visual hierarchy to guide users", "type": "fact"}, {"text": "Service circulation: separate from public (trash, deliveries, mechanical access)", "type": "fact"}, {"text": "Standards Applied: NBCP Exiting Requirements, Architectural Design Principles", "type": "concept"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-DSGN-007-03';

